import { Component, DestroyRef, ElementRef, inject, input, signal, viewChild, OnInit } from '@angular/core';
import { CommonModule, DatePipe } from '@angular/common';
import { QuillModule, ContentChange } from 'ngx-quill';
import { interval, EMPTY } from 'rxjs';
import { switchMap, catchError } from 'rxjs/operators';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { MensajeService } from '../../../../shared/services/mensaje.service';
import { AuthService } from '../../../../services/auth.service';
import { ToastService } from '../../../../shared/services/toast.service';
import { extractErrorMessage } from '../../../../shared/utils/error-utils';
import type { Mensaje } from '../../../../shared/models/mensaje.model';
import type Quill from 'quill';

@Component({
  selector: 'app-chat-inversor',
  imports: [CommonModule, QuillModule, DatePipe],
  templateUrl: './chat-inversor.component.html',
})
export class ChatInversorComponent implements OnInit {
  private readonly mensajeService = inject(MensajeService);
  protected readonly authService = inject(AuthService);
  private readonly toastService = inject(ToastService);
  private readonly destroyRef = inject(DestroyRef);
  readonly folio = input.required<string>();
  readonly mensajes = signal<Mensaje[]>([]);
  readonly loading = signal(false);
  readonly ultimoId = signal<number | undefined>(undefined);
  readonly enviando = signal(false);
  readonly chatContainer = viewChild<ElementRef<HTMLDivElement>>('chatContainer');
  readonly contenido = signal('');
  private quillEditor: Quill | null = null;

  ngOnInit(): void {
    this.cargarMensajes();

    interval(5000).pipe(
      takeUntilDestroyed(this.destroyRef),
      switchMap(() => this.mensajeService.getChatMensajes(this.folio(), this.ultimoId()).pipe(
        catchError((err) => {
          this.toastService.error(extractErrorMessage(err));
          return EMPTY;
        }),
      )),
    ).subscribe({
      next: (nuevos) => {
        if (nuevos.length > 0) {
          this.mensajes.update(prev => [...prev, ...nuevos]);
          this.ultimoId.set(nuevos[nuevos.length - 1].id);
          setTimeout(() => this.scrollAlFinal());
        }
      },
    });
  }

  cargarMensajes(): void {
    this.loading.set(true);
    this.mensajeService.getChatMensajes(this.folio()).subscribe({
      next: (mensajes) => {
        this.mensajes.set(mensajes);
        this.loading.set(false);
        if (mensajes.length > 0) {
          this.ultimoId.set(mensajes[mensajes.length - 1].id);
        }
        setTimeout(() => this.scrollAlFinal());
      },
      error: (err) => {
        this.loading.set(false);
        this.toastService.error(extractErrorMessage(err));
      },
    });
  }

  enviarMensaje(): void {
    const html = this.contenido().trim();
    if (!html || this.enviando()) return;

    this.enviando.set(true);
    this.mensajeService.createMensaje(this.folio(), { contenido: html, tipo: 'chat' }).subscribe({
      next: (mensaje) => {
        this.mensajes.update(prev => [...prev, mensaje]);
        this.ultimoId.set(mensaje.id);
        this.contenido.set('');
        if (this.quillEditor) {
          this.quillEditor.setText('');
        }
        this.enviando.set(false);
        setTimeout(() => this.scrollAlFinal());
      },
      error: (err) => {
        this.enviando.set(false);
        this.toastService.error(extractErrorMessage(err));
      },
    });
  }

  private scrollAlFinal(): void {
    const el = this.chatContainer()?.nativeElement;
    if (el) {
      el.scrollTop = el.scrollHeight;
    }
  }

  onEditorCreated(editor: Quill): void {
    this.quillEditor = editor;
  }

  onContentChanged(event: ContentChange): void {
    this.contenido.set(event.html || '');
  }

  esPropio(msg: Mensaje): boolean {
    const user = this.authService.currentUser();
    return user ? msg.autor.id === user.id : false;
  }
}
